/**
 * Google Apps Script for Infection Control Reporting System
 * Password Protected Settings: "11193"
 */

// --- Initial Setup ---
function doGet() {
  return HtmlService.createTemplateFromFile('index')
      .evaluate()
      .setTitle('نظام تقارير مكافحة العدوى')
      .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL)
      .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}

/**
 * Run this function ONCE to set up the Google Sheet structure automatically.
 */
function setupSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 1. Data Sheet
  let dataSheet = ss.getSheetByName('Data');
  if (!dataSheet) {
    dataSheet = ss.insertSheet('Data');
    dataSheet.appendRow(['Date', 'Month', 'Year', 'Period', 'Department', 'Inspector', 'Supervisor', 'Procedure', 'Status', 'Note', 'Recommendation', 'Timestamp']);
    dataSheet.setFrozenRows(1);
  }

  // 2. Settings Sheet
  let settingsSheet = ss.getSheetByName('Settings');
  if (!settingsSheet) {
    settingsSheet = ss.insertSheet('Settings');
    settingsSheet.appendRow(['Departments', 'Periods', 'Inspectors', 'Procedures', 'DefaultNotes', 'DefaultRecs']);
    // Add some dummy data
    settingsSheet.getRange(2, 1, 3, 4).setValues([
      ['طوارئ', 'صباحية', 'د. محمد', 'غسل الأيدي'],
      ['عناية مركزة', 'مسائية', 'م. سارة', 'ارتداء الواقيات الشخصية'],
      ['عمليات', 'ليلية', 'د. أحمد', 'التخلص الآمن من النفايات']
    ]);
  }
}

// --- Security ---
function verifyPassword(password) {
  // Server-side check for security
  return password === '11193';
}

// --- Data Operations ---

/**
 * Save Daily Report
 */
function saveDailyReport(formData) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName('Data');
  const timestamp = new Date();
  const month = new Date(formData.date).getMonth() + 1;
  const year = new Date(formData.date).getFullYear();

  const rows = formData.evaluations.map(item => {
    return [
      formData.date,      // Date
      month,              // Month (derived)
      year,               // Year (derived)
      formData.period,    // Period
      formData.department,// Department
      formData.inspector, // Inspector
      formData.supervisor,// Supervisor
      item.procedure,     // Procedure Name
      item.status,        // Yes/No/NA
      item.note,          // Note (if No)
      item.rec,           // Recommendation (if No)
      timestamp           // Timestamp
    ];
  });

  if (rows.length > 0) {
    sheet.getRange(sheet.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
  }
  return { success: true };
}

/**
 * Get Settings (Departments, Periods, etc.)
 */
function getSettings() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName('Settings');
  const data = sheet.getDataRange().getValues();
  const headers = data.shift(); // Remove headers

  const settings = {
    departments: [],
    periods: [],
    inspectors: [],
    procedures: [] // Each procedure is object {name, defaultNote, defaultRec}
  };

  // Helper to extract column data without empty cells
  const getCol = (index) => data.map(r => r[index]).filter(String);

  settings.departments = getCol(0);
  settings.periods = getCol(1);
  settings.inspectors = getCol(2);

  // Procedures are complex, stored in separate cols but linked by index in UI logic usually
  // Here we map them simply.
  const procNames = getCol(3);
  const defNotes = getCol(4);
  const defRecs = getCol(5);

  settings.procedures = procNames.map((name, i) => ({
    name: name,
    note: defNotes[i] || '',
    rec: defRecs[i] || ''
  }));

  return settings;
}

/**
 * Update Settings
 */
function saveSettingsData(newSettings) {
  if (!verifyPassword(newSettings.password)) {
    throw new Error("Wrong Password");
  }

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('Settings');
  sheet.clearContents();

  // Reconstruct the grid
  const headers = ['Departments', 'Periods', 'Inspectors', 'Procedures', 'DefaultNotes', 'DefaultRecs'];

  // Find max length to create the grid
  const maxLen = Math.max(
    newSettings.departments.length,
    newSettings.periods.length,
    newSettings.inspectors.length,
    newSettings.procedures.length
  );

  const data = [];
  data.push(headers);

  for (let i = 0; i < maxLen; i++) {
    const proc = newSettings.procedures[i] || {};
    data.push([
      newSettings.departments[i] || '',
      newSettings.periods[i] || '',
      newSettings.inspectors[i] || '',
      proc.name || '',
      proc.note || '',
      proc.rec || ''
    ]);
  }

  if (data.length > 0) {
    sheet.getRange(1, 1, data.length, 6).setValues(data);
  }
  return { success: true };
}

/**
 * Fetch Data for Dashboard and Reports
 */
function getReportData(filterType, filterValue) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName('Data');
  const data = sheet.getDataRange().getValues();
  const headers = data.shift(); // Remove headers

  // Indices based on setupSheet:
  // 0:Date, 1:Month, 2:Year, 3:Period, 4:Dept, 5:Inspector, 6:Supervisor, 7:Procedure, 8:Status, 9:Note, 10:Rec

  // Filter Logic
  let filteredData = data;

  if (filterType === 'daily') {
    // filterValue is date string 'YYYY-MM-DD'
    filteredData = data.filter(row => {
      let d = new Date(row[0]);
      // simple ISO comparison
      return d.toISOString().split('T')[0] === filterValue;
    });
  } else if (filterType === 'monthly') {
     // filterValue is 'YYYY-MM'
     const [y, m] = filterValue.split('-');
     filteredData = data.filter(row => row[2] == y && row[1] == parseInt(m)); // loose equality for string/number
  } else if (filterType === 'yearly') {
     // filterValue is 'YYYY'
     filteredData = data.filter(row => row[2] == filterValue);
  } else if (filterType === 'range') {
     // filterValue is {start: 'YYYY-MM-DD', end: 'YYYY-MM-DD'}
     const start = new Date(filterValue.start);
     const end = new Date(filterValue.end);
     filteredData = data.filter(row => {
       const d = new Date(row[0]);
       return d >= start && d <= end;
     });
  }

  return filteredData; // Return raw rows to frontend for processing (counting stats, etc.)
}

/**
 * Get All Data for Dashboard (Aggregated)
 */
function getDashboardMetrics() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName('Data');
  const data = sheet.getDataRange().getValues();
  data.shift(); // remove header

  // Return all data to client to let Chart.js handle aggregation (easier for dynamic filtering)
  // To optimize for large datasets, we would aggregate here. For this app scope, sending data is fine.
  return data.map(r => ({
    date: r[0],
    dept: r[4],
    status: r[8]
  }));
}

