// SHA-256 hash for "11193"
const ADMIN_HASH = 'b02d8291471d248a397441a63c6c193f412c792121300958ce74b47000219665';

function verifyPassword(password) {
  if (!password) return false;

  const rawHash = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, password.toString());
  let txtHash = '';
  for (let i = 0; i < rawHash.length; i++) {
    let hashVal = rawHash[i];
    if (hashVal < 0) {
      hashVal += 256;
    }
    if (hashVal.toString(16).length == 1) {
      txtHash += '0';
    }
    txtHash += hashVal.toString(16);
  }

  return txtHash === ADMIN_HASH;
}

