function renderArchive(rows) {
    const container = document.getElementById('archive-result');
    container.classList.remove('hidden');

    // Clear container
    container.innerHTML = '';

    if (rows.length === 0) {
         container.innerHTML = '<div class="text-center text-gray-500 py-10 bg-gray-50 border border-dashed border-gray-300 rounded">لا توجد بيانات مطابقة للبحث</div>';
         return;
    }

    // Aggregate Data by Report (Date + Period + Dept + Inspector)
    const reports = {};

    rows.forEach(r => {
        // r[0] is Date. 
        const d = new Date(r[0]);
        const dateStr = d.toLocaleDateString('en-CA'); // YYYY-MM-DD

        const period = r[3];
        const dept = r[4];
        const inspector = r[5];
        const status = r[8]; // Yes, No, NA

        // Create a unique key for the report
        const key = `${dateStr}_${period}_${dept}_${inspector}`;

        if (!reports[key]) {
            reports[key] = {
                date: dateStr,
                period: period,
                dept: dept,
                inspector: inspector,
                yesCount: 0,
                noCount: 0
            };
        }

        if (status === 'Yes') reports[key].yesCount++;
        if (status === 'No') reports[key].noCount++;
    });

    // Convert to array
    const reportList = Object.values(reports);

    // Sort by Date Descending
    reportList.sort((a, b) => new Date(b.date) - new Date(a.date));

    // Build HTML Table
    let html = `
        <div class="flex justify-between items-center mb-6 no-print">
            <h3 class="font-bold text-xl text-blue-900"><i class="fas fa-list-ul ml-2"></i> نتائج البحث (${reportList.length} تقرير)</h3>
            <button onclick="window.print()" class="bg-gray-800 text-white px-5 py-2 rounded shadow hover:bg-gray-700 transition flex items-center">
                <i class="fas fa-print ml-2"></i> طباعة القائمة
            </button>
        </div>

        <div class="overflow-x-auto rounded-lg border border-gray-200 shadow-sm">
            <table class="w-full text-sm text-right bg-white">
                <thead class="bg-blue-900 text-white">
                    <tr>
                        <th class="p-4 font-bold border-b border-blue-800">التاريخ</th>
                        <th class="p-4 font-bold border-b border-blue-800">الفترة</th>
                        <th class="p-4 font-bold border-b border-blue-800">القسم</th>
                        <th class="p-4 font-bold border-b border-blue-800">القائم بالمرور</th>
                        <th class="p-4 font-bold border-b border-blue-800 text-center">نسبة الالتزام</th>
                    </tr>
                </thead>
                <tbody class="divide-y divide-gray-100">
    `;

    reportList.forEach(rep => {
        const total = rep.yesCount + rep.noCount;
        const score = total === 0 ? 0 : Math.round((rep.yesCount / total) * 100);

        let badgeClass = 'bg-red-100 text-red-800';
        if (score >= 80) badgeClass = 'bg-green-100 text-green-800';
        else if (score >= 50) badgeClass = 'bg-orange-100 text-orange-800';

        html += `
            <tr class="hover:bg-blue-50 transition text-gray-700">
                <td class="p-4 font-medium">${rep.date}</td>
                <td class="p-4">${rep.period}</td>
                <td class="p-4 font-bold text-gray-900">${rep.dept}</td>
                <td class="p-4">${rep.inspector}</td>
                <td class="p-4 text-center">
                    <span class="px-3 py-1 rounded-full text-xs font-bold ${badgeClass}">
                        ${score}%
                    </span>
                </td>
            </tr>
        `;
    });

    html += `
                </tbody>
            </table>
        </div>
    `;

    container.innerHTML = html;
}

