function quickSetDate(type, triggerSearch = true) {
    const now = new Date();
    const startEl = document.getElementById('arch-start');
    const endEl = document.getElementById('arch-end');

    // Helper to format as YYYY-MM-DD using local time
    const toLocalYMD = (date) => {
        const offset = date.getTimezoneOffset() * 60000;
        return new Date(date.getTime() - offset).toISOString().split('T')[0];
    };

    if (type === 'today') {
        const str = toLocalYMD(now);
        startEl.value = str;
        endEl.value = str;
    } else if (type === 'month') {
        const start = new Date(now.getFullYear(), now.getMonth(), 1);
        startEl.value = toLocalYMD(start);
        endEl.value = toLocalYMD(now);
    } else if (type === 'year') {
        const start = new Date(now.getFullYear(), 0, 1);
        startEl.value = toLocalYMD(start);
        endEl.value = toLocalYMD(now);
    }

    if (triggerSearch) generateArchive();
}

