function getReportData(filterType, filterValue) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('Data');

  if (!sheet) {
    setupSheet();
    sheet = ss.getSheetByName('Data');
  }

  const data = sheet.getDataRange().getValues();
  if (data.length === 0) return []; // Empty sheet protection

  const headers = data.shift(); // Remove headers

  // Indices based on setupSheet:
  // 0:Date, 1:Month, 2:Year, 3:Period, 4:Dept, 5:Inspector, 6:Supervisor, 7:Procedure, 8:Status, 9:Note, 10:Rec

  // Filter Logic
  let filteredData = data;

  if (filterType === 'daily') {
    // filterValue is date string 'YYYY-MM-DD'
    filteredData = data.filter(row => {
      if (!row[0]) return false;
      let d = new Date(row[0]);
      // Use local YYYY-MM-DD comparison or simple string check if input matches sheet format
      // Safe way: format date object to YYYY-MM-DD
      let y = d.getFullYear();
      let m = String(d.getMonth() + 1).padStart(2, '0');
      let day = String(d.getDate()).padStart(2, '0');
      return `${y}-${m}-${day}` === filterValue;
    });
  } else if (filterType === 'monthly') {
     // filterValue is 'YYYY-MM'
     const [y, m] = filterValue.split('-');
     filteredData = data.filter(row => row[2] == y && row[1] == parseInt(m)); // loose equality for string/number
  } else if (filterType === 'yearly') {
     // filterValue is 'YYYY'
     filteredData = data.filter(row => row[2] == filterValue);
  } else if (filterType === 'range') {
     // filterValue is {start: 'YYYY-MM-DD', end: 'YYYY-MM-DD'}
     const start = new Date(filterValue.start);
     start.setHours(0, 0, 0, 0); // Start of day

     const end = new Date(filterValue.end);
     end.setHours(23, 59, 59, 999); // End of day inclusive

     filteredData = data.filter(row => {
       const cellDate = row[0];
       if (!cellDate) return false;
       const d = new Date(cellDate);
       if (isNaN(d.getTime())) return false; // Invalid date check
       return d >= start && d <= end;
     });
  }

  return filteredData; // Return raw rows to frontend for processing (counting stats, etc.)
}

