/**
 * Setup Spreadsheet Structure (Run once or checks on load)
 * @param {Spreadsheet} optSS - Optional spreadsheet instance to avoid recursive calls
 */
function setupSheet(optSS) {
  // Use the passed instance or fetch safely
  const ss = optSS || getSS();

  // 1. Data Sheet
  let dataSheet = ss.getSheetByName('Data');
  if (!dataSheet) {
    dataSheet = ss.insertSheet('Data');
    dataSheet.appendRow(['Date', 'Month', 'Year', 'Period', 'Department', 'Inspector', 'Supervisor', 'Procedure', 'Status', 'Note', 'Recommendation', 'Timestamp']);
    dataSheet.setFrozenRows(1);
    // Remove default Sheet1 if it exists and we just created Data
    const defaultSheet = ss.getSheetByName('Sheet1');
    if (defaultSheet) ss.deleteSheet(defaultSheet);
  }

  // 2. Settings Sheet
  let settingsSheet = ss.getSheetByName('Settings');
  if (!settingsSheet) {
    settingsSheet = ss.insertSheet('Settings');
    settingsSheet.appendRow(['Key', 'Value (JSON)']);
    // Default Settings
    const defaults = [
      ['admin_password', JSON.stringify('123456')],
      ['departments', JSON.stringify(['طوارئ', 'عناية مركزة', 'عمليات', 'عيادات خارجية', 'معمل', 'أشعة'])],
      ['periods', JSON.stringify(['صباحية', 'مسائية', 'سهر'])],
      ['inspectors', JSON.stringify(['د. أحمد', 'د. محمد', 'أ. سارة'])],
      ['procedures', JSON.stringify([
         {name: 'غسل الأيدي', note: 'عدم الالتزام باللحظات الخمس', rec: 'إعادة التدريب', depts: []},
         {name: 'ارتداء الواقيات الشخصية', note: 'عدم ارتداء الماسك/الجوانتي', rec: 'توفير المستلزمات', depts: []},
         {name: 'فرز النفايات', note: 'خلط النفايات', rec: 'توفير أكياس ملونة', depts: []},
         {name: 'تعقيم الآلات', note: 'قصور في الدورة التعقيمية', rec: 'صيانة الأوتوكلاف', depts: ['عمليات', 'طوارئ']}
      ])]
    ];
    defaults.forEach(row => settingsSheet.appendRow(row));
  }
}

/**
 * Save Daily Report
 */
function saveDailyReport(form) {
  const ss = getSS();
  let sheet = ss.getSheetByName('Data');
  // Ensure structure exists
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Data'); }

  // Create a Date object from the input string (YYYY-MM-DD)
  // We use new Date(form.date) which parses as UTC midnight usually, 
  // but it's safer to store as a Date object in Sheets for sorting.
  const dateObj = new Date(form.date);
  const month = dateObj.getMonth() + 1;
  const year = dateObj.getFullYear();
  const timestamp = new Date();

  const rows = form.evaluations.map(e => {
    return [
      dateObj,        // 0: Store as Date Object
      month,          // 1
      year,           // 2
      form.period,    // 3
      form.department,// 4
      form.inspector, // 5
      form.supervisor,// 6
      e.procedure,    // 7
      e.status,       // 8
      e.note,         // 9
      e.rec,          // 10
      timestamp       // 11
    ];
  });

  if (rows.length > 0) {
    sheet.getRange(sheet.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
  }
  return {success: true};
}

/**
 * Fetch Report Data
 */
function getReportData(filterType, filterValue) {
  const ss = getSS();
  let sheet = ss.getSheetByName('Data');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Data'); }

  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return []; // Only headers

  const headers = data.shift(); // Remove headers

  // Indices: 0:Date, 1:Month, 2:Year, 3:Period, 4:Dept, 5:Inspector, 6:Supervisor, 7:Procedure, 8:Status

  let filteredData = data;

  // Helper to safely get Date object
  const parseDate = (d) => {
    if (d instanceof Date) return d;
    if (typeof d === 'string') return new Date(d);
    return null;
  };

  // Helper to format Date to YYYY-MM-DD string to avoid timezone issues on client
  const formatDateStr = (d) => {
    if (!d) return "";
    const date = parseDate(d);
    if (!date || isNaN(date.getTime())) return "";
    // Format using the script's timezone (or UTC if preferred, but simple string concat is safest for YMD)
    // Using getFullYear, getMonth, getDate acts on local script time.
    // If the sheet cell is a Date, GAS reads it in script time.
    let y = date.getFullYear();
    let m = String(date.getMonth() + 1).padStart(2, '0');
    let day = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  };

  if (filterType === 'daily') {
    // filterValue = 'YYYY-MM-DD'
    filteredData = data.filter(row => {
      const dStr = formatDateStr(row[0]);
      return dStr === filterValue;
    });
  } else if (filterType === 'monthly') {
     // filterValue = 'YYYY-MM'
     const [y, m] = filterValue.split('-');
     filteredData = data.filter(row => row[2] == y && row[1] == parseInt(m));
  } else if (filterType === 'yearly') {
     // filterValue = 'YYYY'
     filteredData = data.filter(row => row[2] == filterValue);
  } else if (filterType === 'range') {
     // filterValue = {start: 'YYYY-MM-DD', end: 'YYYY-MM-DD'}
     const start = new Date(filterValue.start);
     start.setHours(0, 0, 0, 0); 
     const end = new Date(filterValue.end);
     end.setHours(23, 59, 59, 999); 

     filteredData = data.filter(row => {
       const d = parseDate(row[0]);
       if (!d) return false;
       return d >= start && d <= end;
     });
  }

  // Convert dates to simple string YYYY-MM-DD for client
  return filteredData.map(row => {
    let r = [...row];
    r[0] = formatDateStr(row[0]); // Replace Date object with string
    // row[11] is timestamp, let's ISO string that one
    if (r[11] instanceof Date) r[11] = r[11].toISOString();
    return r;
  });
}

/**
 * Dashboard Metrics
 */
function getDashboardMetrics() {
  const ss = getSS();
  let sheet = ss.getSheetByName('Data');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Data'); }

  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return [];
  data.shift(); // remove header

  // Return simplified object list: {date, dept, status}
  return data.map(r => {
    let dStr = "";
    if (r[0] instanceof Date) {
       let m = String(r[0].getMonth() + 1).padStart(2, '0');
       let day = String(r[0].getDate()).padStart(2, '0');
       dStr = `${r[0].getFullYear()}-${m}-${day}`;
    } else {
       dStr = String(r[0]);
    }

    return {
      date: dStr, // Return YYYY-MM-DD string
      dept: r[4],
      status: r[8]
    };
  });
}

/**
 * Settings Management
 */
function getSettings() {
  const ss = getSS();
  let sheet = ss.getSheetByName('Settings');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Settings'); }

  const data = sheet.getDataRange().getValues();
  const settings = {};

  // Skip header
  for (let i = 1; i < data.length; i++) {
    const key = data[i][0];
    const val = data[i][1];
    try {
      settings[key] = JSON.parse(val);
    } catch (e) {
      settings[key] = val;
    }
  }
  return settings;
}

function saveSettingsData(newSettings) {
  const ss = getSS();
  let sheet = ss.getSheetByName('Settings');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Settings'); }

  // Clear and rewrite
  sheet.clearContents();
  sheet.appendRow(['Key', 'Value (JSON)']);

  sheet.appendRow(['admin_password', JSON.stringify(newSettings.password)]);
  sheet.appendRow(['departments', JSON.stringify(newSettings.departments)]);
  sheet.appendRow(['periods', JSON.stringify(newSettings.periods)]);
  sheet.appendRow(['inspectors', JSON.stringify(newSettings.inspectors)]);
  sheet.appendRow(['procedures', JSON.stringify(newSettings.procedures)]);

  return true;
}

function verifyPassword(inputPass) {
  const settings = getSettings();
  // Default to '123456' if not set
  let savedPass = settings.admin_password;
  if (savedPass === undefined || savedPass === null || savedPass === '') {
    savedPass = '123456';
  }

  // Convert both to string and trim to ensure robust comparison
  return String(savedPass).trim() === String(inputPass).trim();
}

function renderArchive(rows, filters) {
    const container = document.getElementById('archive-result');
    const detailContainer = document.getElementById('archive-detail-view');
    const batchContainer = document.getElementById('archive-batch-view');

    container.classList.remove('hidden');
    detailContainer.classList.add('hidden');
    batchContainer.classList.add('hidden');
    container.innerHTML = '';

    if (rows.length === 0) {
         container.innerHTML = '<div class="text-center text-gray-500 py-10 bg-gray-50 border border-dashed border-gray-300 rounded">لا توجد بيانات مطابقة للبحث</div>';
         return;
    }

    const reports = {};
    rows.forEach(r => {
        // r[0] is now a formatted YYYY-MM-DD string from the server
        const dateStr = r[0] || 'Unknown Date';

        const key = `${dateStr}_${r[3]}_${r[4]}_${r[5]}`;

        if (!reports[key]) {
            reports[key] = { date: dateStr, period: r[3], dept: r[4], inspector: r[5], supervisor: r[6], yesCount: 0, noCount: 0, rows: [] };
        }
        if (r[8] === 'Yes') reports[key].yesCount++;
        if (r[8] === 'No') reports[key].noCount++;
        reports[key].rows.push(r);
    });

    currentArchiveReports = Object.values(reports);
    currentArchiveReports.sort((a, b) => b.date.localeCompare(a.date));

    // Print Header (Visible only in print)
    const printHeader = `
        <div class="hidden print-only mb-6 border-b-2 border-black pb-4 text-center">
            <h1 class="text-2xl font-bold mb-2">سجل تقارير مرور مكافحة العدوى</h1>
            <div class="flex flex-wrap justify-center gap-6 text-sm font-bold">
                <span>من تاريخ: ${filters?.start || '-'}</span>
                <span>إلى تاريخ: ${filters?.end || '-'}</span>
                <span>القسم: ${filters?.dept || 'الكل'}</span>
                <span>القائم بالمرور: ${filters?.insp || 'الكل'}</span>
            </div>
            <div class="mt-2 text-xs text-gray-600">تاريخ الطباعة: ${new Date().toLocaleDateString('en-CA')}</div>
        </div>
    `;

    let html = `
        ${printHeader}
        <div class="flex justify-between items-center mb-4 no-print">
            <h3 class="font-bold text-xl text-blue-900"><i class="fas fa-list-ul ml-2"></i> نتائج البحث (${currentArchiveReports.length} تقرير)</h3>
            <div class="flex gap-2">
                <button onclick="printSelectedReports()" class="bg-emerald-600 text-white px-4 py-2 rounded shadow hover:bg-emerald-700 transition flex items-center text-sm">
                    <i class="fas fa-print ml-2"></i> طباعة المحدد
                </button>
                <button onclick="window.print()" class="bg-gray-800 text-white px-4 py-2 rounded shadow hover:bg-gray-700 transition flex items-center text-sm">
                    <i class="fas fa-list ml-2"></i> طباعة القائمة
                </button>
            </div>
        </div>
        <div class="mb-6 no-print relative">
            <input type="text" id="archive-filter-input" onkeyup="filterArchiveTable()" placeholder="تصفية النتائج (ابحث عن قسم، تاريخ، أو نسبة...)" 
                   class="w-full border border-gray-300 p-3 pr-10 rounded shadow-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition">
            <i class="fas fa-search absolute left-3 top-4 text-gray-400"></i>
        </div>
        <div class="overflow-x-auto rounded-lg border border-gray-200 shadow-sm">
            <table id="archive-table" class="w-full text-sm text-right bg-white">
                <thead class="bg-blue-900 text-white">
                    <tr>
                        <th class="p-4 font-bold border-b border-blue-800 w-10 text-center no-print">
                            <input type="checkbox" id="archive-select-all" onclick="toggleSelectAllArchive(this)" class="w-4 h-4 accent-blue-300">
                        </th>
                        <th class="p-4 font-bold border-b border-blue-800">التاريخ</th>
                        <th class="p-4 font-bold border-b border-blue-800">الفترة</th>
                        <th class="p-4 font-bold border-b border-blue-800">القسم</th>
                        <th class="p-4 font-bold border-b border-blue-800">القائم بالمرور</th>
                        <th class="p-4 font-bold border-b border-blue-800 text-center">نسبة الالتزام</th>
                        <th class="p-4 font-bold border-b border-blue-800 w-24 no-print">إجراءات</th>
                    </tr>
                </thead>
                <tbody class="divide-y divide-gray-100">
    `;

    currentArchiveReports.forEach((rep, index) => {
        const total = rep.yesCount + rep.noCount;
        const score = total === 0 ? 0 : Math.round((rep.yesCount / total) * 100);
        let badgeClass = 'bg-red-100 text-red-800';
        if (score >= 80) badgeClass = 'bg-green-100 text-green-800';
        else if (score >= 50) badgeClass = 'bg-orange-100 text-orange-800';

        html += `
            <tr class="hover:bg-blue-50 transition text-gray-700">
                <td class="p-4 text-center no-print">
                    <input type="checkbox" class="archive-chk w-4 h-4 accent-blue-600" value="${index}">
                </td>
                <td class="p-4 font-medium">${rep.date}</td>
                <td class="p-4">${rep.period}</td>
                <td class="p-4 font-bold text-gray-900">${rep.dept}</td>
                <td class="p-4">${rep.inspector}</td>
                <td class="p-4 text-center"><span class="px-3 py-1 rounded-full text-xs font-bold ${badgeClass}">${score}%</span></td>
                <td class="p-4 text-center no-print">
                     <button onclick="viewArchiveReport(${index})" class="bg-blue-600 text-white px-3 py-1 rounded text-xs hover:bg-blue-700 transition">عرض التفاصيل</button>
                </td>
            </tr>
        `;
    });
    html += `</tbody></table></div>`;

    // Print Footer
    html += `
        <div class="mt-8 hidden print-only text-center text-sm font-bold pt-4 border-t border-gray-400">
            <div class="flex justify-around">
                <span>توقيع مسؤول مكافحة العدوى</span>
                <span>يعتمد، مدير المستشفى</span>
            </div>
        </div>
    `;

    container.innerHTML = html;
}

