function processPeriodicData(rows, type, dateVal) {
    if(rows.length === 0) { alert('لا توجد بيانات لهذه الفترة'); return; }

    let totalYes = 0, totalNo = 0;
    rows.forEach(r => {
        if(r[8] === 'Yes') totalYes++;
        if(r[8] === 'No') totalNo++;
    });
    const hospScore = totalYes + totalNo === 0 ? 0 : Math.round((totalYes / (totalYes+totalNo)) * 100);

    const depts = {}; 
    rows.forEach(r => {
        const d = r[4];
        const status = r[8];
        const note = r[9];
        const rec = r[10];

        if(!depts[d]) depts[d] = {yes:0, no:0, notes:{}};
        if(status === 'Yes') depts[d].yes++;
        if(status === 'No') {
            depts[d].no++;
            if(note) {
                if(!depts[d].notes[note]) depts[d].notes[note] = {count:0, rec:rec};
                depts[d].notes[note].count++;
            }
        }
    });

    const container = type === 'monthly' ? document.getElementById('monthly-result') : document.getElementById('yearly-result');
    container.classList.remove('hidden');
