function printSelectedReports() {
    const checkboxes = document.querySelectorAll('.archive-chk:checked');
    if (checkboxes.length === 0) {
        alert("الرجاء تحديد تقرير واحد على الأقل للطباعة");
        return;
    }

    const batchContainer = document.getElementById('archive-batch-view');
    const contentDiv = document.getElementById('archive-batch-content');

    // Hide list, show batch
    document.getElementById('archive-result').classList.add('hidden');
    batchContainer.classList.remove('hidden');

    // Group selected reports by Date
    const groupedByDate = {};

    checkboxes.forEach((cb) => {
        const index = parseInt(cb.value);
        const report = currentArchiveReports[index];
        if (report) {
            if (!groupedByDate[report.date]) {
                groupedByDate[report.date] = [];
            }
            groupedByDate[report.date].push(report);
        }
    });

    let htmlAccumulator = '';
    const dates = Object.keys(groupedByDate).sort().reverse(); // Show newest dates first

    dates.forEach((date, idx) => {
        const reports = groupedByDate[date];
        htmlAccumulator += buildCombinedDailyReport(date, reports);

        // Add page break if it's not the last date
        if (idx < dates.length - 1) {
            htmlAccumulator += '<div class="page-break"></div>';
        }
    });

    contentDiv.innerHTML = htmlAccumulator;
}

