// --- Configuration ---
// اترك هذا المتغير فارغاً، سيقوم النظام بتعبئته تلقائياً أو إنشاء شيت جديد.
const SPREADSHEET_ID = ''; 

/**
 * Helper to get the Spreadsheet instance safely
 * Logic:
 * 1. Try Active Sheet (if bound).
 * 2. Try Hardcoded ID.
 * 3. Try Auto-saved ID in Script Properties.
 * 4. Create NEW Sheet if all else fails.
 */
function getSS() {
  let ss = null;

  // 1. Try getting the active spreadsheet (works if script is container-bound)
  try {
    ss = SpreadsheetApp.getActiveSpreadsheet();
  } catch (e) {}

  // 2. If not found, try opening by ID if provided constant is set
  if (!ss && SPREADSHEET_ID) {
    try {
      ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    } catch (e) {}
  }

  // 3. Try retrieving the ID of a previously created/saved sheet
  if (!ss) {
    const props = PropertiesService.getScriptProperties();
    const storedId = props.getProperty('TARGET_SS_ID');
    if (storedId) {
      try {
        ss = SpreadsheetApp.openById(storedId);
      } catch (e) {
        // Stored ID might be invalid/deleted, ignore and proceed to create new
      }
    }
  }

  // 4. If still null, CREATE a new Spreadsheet automatically
  if (!ss) {
    try {
      ss = SpreadsheetApp.create('نظام مكافحة العدوى - قاعدة بيانات');
      // Save the ID so we use the same sheet next time
      PropertiesService.getScriptProperties().setProperty('TARGET_SS_ID', ss.getId());
      // Initialize it immediately
      setupSheet(ss); 
    } catch (e) {
      throw new Error("خطأ حرج: لم يتمكن النظام من الوصول لملف البيانات ولا إنشاء ملف جديد. يرجى التأكد من تشغيل التطبيق بصلاحيات (Execute as: Me). التفاصيل: " + e.message);
    }
  }

  return ss;
}

/**
 * Serve the HTML page
 */
function doGet() {
  return HtmlService.createTemplateFromFile('index')
      .evaluate()
      .setTitle('نظام تقارير مكافحة العدوى')
      .addMetaTag('viewport', 'width=device-width, initial-scale=1')
      .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/**
 * Setup Spreadsheet Structure (Run once or checks on load)
 * @param {Spreadsheet} optSS - Optional spreadsheet instance to avoid recursive calls
 */
function setupSheet(optSS) {
  // Use the passed instance or fetch safely
  const ss = optSS || getSS();

  // 1. Data Sheet
  let dataSheet = ss.getSheetByName('Data');
  if (!dataSheet) {
    dataSheet = ss.insertSheet('Data');
    dataSheet.appendRow(['Date', 'Month', 'Year', 'Period', 'Department', 'Inspector', 'Supervisor', 'Procedure', 'Status', 'Note', 'Recommendation', 'Timestamp']);
    dataSheet.setFrozenRows(1);
    // Remove default Sheet1 if it exists and we just created Data
    const defaultSheet = ss.getSheetByName('Sheet1');
    if (defaultSheet) ss.deleteSheet(defaultSheet);
  }

  // 2. Settings Sheet
  let settingsSheet = ss.getSheetByName('Settings');
  if (!settingsSheet) {
    settingsSheet = ss.insertSheet('Settings');
    settingsSheet.appendRow(['Key', 'Value (JSON)']);
    // Default Settings
    const defaults = [
      ['admin_password', JSON.stringify('123456')],
      ['departments', JSON.stringify(['طوارئ', 'عناية مركزة', 'عمليات', 'عيادات خارجية', 'معمل', 'أشعة'])],
      ['periods', JSON.stringify(['صباحية', 'مسائية', 'سهر'])],
      ['inspectors', JSON.stringify(['د. أحمد', 'د. محمد', 'أ. سارة'])],
      ['procedures', JSON.stringify([
         {name: 'غسل الأيدي', note: 'عدم الالتزام باللحظات الخمس', rec: 'إعادة التدريب', depts: []},
         {name: 'ارتداء الواقيات الشخصية', note: 'عدم ارتداء الماسك/الجوانتي', rec: 'توفير المستلزمات', depts: []},
         {name: 'فرز النفايات', note: 'خلط النفايات', rec: 'توفير أكياس ملونة', depts: []},
         {name: 'تعقيم الآلات', note: 'قصور في الدورة التعقيمية', rec: 'صيانة الأوتوكلاف', depts: ['عمليات', 'طوارئ']}
      ])]
    ];
    defaults.forEach(row => settingsSheet.appendRow(row));
  }
}

/**
 * Save Daily Report
 */
function saveDailyReport(form) {
  const ss = getSS();
  let sheet = ss.getSheetByName('Data');
  // Ensure structure exists
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Data'); }

  // Create a Date object from the input string (YYYY-MM-DD)
  // We use new Date(form.date) which parses as UTC midnight usually, 
  // but it's safer to store as a Date object in Sheets for sorting.
  const dateObj = new Date(form.date);
  const month = dateObj.getMonth() + 1;
  const year = dateObj.getFullYear();
  const timestamp = new Date();

  const rows = form.evaluations.map(e => {
    return [
      dateObj,        // 0: Store as Date Object
      month,          // 1
      year,           // 2
      form.period,    // 3
      form.department,// 4
      form.inspector, // 5
      form.supervisor,// 6
      e.procedure,    // 7
      e.status,       // 8
      e.note,         // 9
      e.rec,          // 10
      timestamp       // 11
    ];
  });

  if (rows.length > 0) {
    sheet.getRange(sheet.getLastRow() + 1, 1, rows.length, rows[0].length).setValues(rows);
  }
  return {success: true};
}

/**
 * Fetch Report Data
 */
function getReportData(filterType, filterValue) {
  const ss = getSS();
  let sheet = ss.getSheetByName('Data');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Data'); }

  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return []; // Only headers

  const headers = data.shift(); // Remove headers

  // Indices: 0:Date, 1:Month, 2:Year, 3:Period, 4:Dept, 5:Inspector, 6:Supervisor, 7:Procedure, 8:Status

  let filteredData = data;

  // Helper to safely get Date object
  const parseDate = (d) => {
    if (d instanceof Date) return d;
    if (typeof d === 'string') return new Date(d);
    return null;
  };

  // Helper to format Date to YYYY-MM-DD string to avoid timezone issues on client
  const formatDateStr = (d) => {
    if (!d) return "";
    const date = parseDate(d);
    if (!date || isNaN(date.getTime())) return "";
    // Format using the script's timezone (or UTC if preferred, but simple string concat is safest for YMD)
    // Using getFullYear, getMonth, getDate acts on local script time.
    // If the sheet cell is a Date, GAS reads it in script time.
    let y = date.getFullYear();
    let m = String(date.getMonth() + 1).padStart(2, '0');
    let day = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  };

  if (filterType === 'daily') {
    // filterValue = 'YYYY-MM-DD'
    filteredData = data.filter(row => {
      const dStr = formatDateStr(row[0]);
      return dStr === filterValue;
    });
  } else if (filterType === 'monthly') {
     // filterValue = 'YYYY-MM'
     const [y, m] = filterValue.split('-');
     filteredData = data.filter(row => row[2] == y && row[1] == parseInt(m));
  } else if (filterType === 'yearly') {
     // filterValue = 'YYYY'
     filteredData = data.filter(row => row[2] == filterValue);
  } else if (filterType === 'range') {
     // filterValue = {start: 'YYYY-MM-DD', end: 'YYYY-MM-DD'}
     const start = new Date(filterValue.start);
     start.setHours(0, 0, 0, 0); 
     const end = new Date(filterValue.end);
     end.setHours(23, 59, 59, 999); 

     filteredData = data.filter(row => {
       const d = parseDate(row[0]);
       if (!d) return false;
       return d >= start && d <= end;
     });
  }

  // Convert dates to simple string YYYY-MM-DD for client
  return filteredData.map(row => {
    let r = [...row];
    r[0] = formatDateStr(row[0]); // Replace Date object with string
    // row[11] is timestamp, let's ISO string that one
    if (r[11] instanceof Date) r[11] = r[11].toISOString();
    return r;
  });
}

/**
 * Dashboard Metrics
 */
function getDashboardMetrics() {
  const ss = getSS();
  let sheet = ss.getSheetByName('Data');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Data'); }

  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return [];
  data.shift(); // remove header

  // Return simplified object list: {date, dept, status}
  return data.map(r => {
    let dStr = "";
    if (r[0] instanceof Date) {
       let m = String(r[0].getMonth() + 1).padStart(2, '0');
       let day = String(r[0].getDate()).padStart(2, '0');
       dStr = `${r[0].getFullYear()}-${m}-${day}`;
    } else {
       dStr = String(r[0]);
    }

    return {
      date: dStr, // Return YYYY-MM-DD string
      dept: r[4],
      status: r[8]
    };
  });
}

/**
 * Settings Management
 */
function getSettings() {
  const ss = getSS();
  let sheet = ss.getSheetByName('Settings');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Settings'); }

  const data = sheet.getDataRange().getValues();
  const settings = {};

  // Skip header
  for (let i = 1; i < data.length; i++) {
    const key = data[i][0];
    const val = data[i][1];
    try {
      settings[key] = JSON.parse(val);
    } catch (e) {
      settings[key] = val;
    }
  }
  return settings;
}

function saveSettingsData(newSettings) {
  const ss = getSS();
  let sheet = ss.getSheetByName('Settings');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Settings'); }

  // Clear and rewrite
  sheet.clearContents();
  sheet.appendRow(['Key', 'Value (JSON)']);

  sheet.appendRow(['admin_password', JSON.stringify(newSettings.password)]);
  sheet.appendRow(['departments', JSON.stringify(newSettings.departments)]);
  sheet.appendRow(['periods', JSON.stringify(newSettings.periods)]);
  sheet.appendRow(['inspectors', JSON.stringify(newSettings.inspectors)]);
  sheet.appendRow(['procedures', JSON.stringify(newSettings.procedures)]);

  return true;
}

function verifyPassword(inputPass) {
  const settings = getSettings();
  // Default to '123456' if not set
  let savedPass = settings.admin_password;
  if (savedPass === undefined || savedPass === null || savedPass === '') {
    savedPass = '123456';
  }

  // Convert both to string and trim to ensure robust comparison
  return String(savedPass).trim() === String(inputPass).trim();
}

