// --- Configuration ---
// اترك هذا المتغير فارغاً، سيقوم النظام بتعبئته تلقائياً أو إنشاء شيت جديد.
const SPREADSHEET_ID = ''; 

/**
 * Helper to get the Spreadsheet instance safely
 * Logic:
 * 1. Try Active Sheet (if bound).
 * 2. Try Hardcoded ID.
 * 3. Try Auto-saved ID in Script Properties.
 * 4. Create NEW Sheet if all else fails.
 */
function getSS() {
  let ss = null;

  // 1. Try getting the active spreadsheet (works if script is container-bound)
  try {
    ss = SpreadsheetApp.getActiveSpreadsheet();
  } catch (e) {}

  // 2. If not found, try opening by ID if provided constant is set
  if (!ss && SPREADSHEET_ID) {
    try {
      ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    } catch (e) {}
  }

  // 3. Try retrieving the ID of a previously created/saved sheet
  if (!ss) {
    const props = PropertiesService.getScriptProperties();
    const storedId = props.getProperty('TARGET_SS_ID');
    if (storedId) {
      try {
        ss = SpreadsheetApp.openById(storedId);
      } catch (e) {
        // Stored ID might be invalid/deleted, ignore and proceed to create new
      }
    }
  }

  // 4. If still null, CREATE a new Spreadsheet automatically
  if (!ss) {
    try {
      ss = SpreadsheetApp.create('نظام مكافحة العدوى - قاعدة بيانات');
      // Save the ID so we use the same sheet next time
      PropertiesService.getScriptProperties().setProperty('TARGET_SS_ID', ss.getId());
      // Initialize it immediately
      setupSheet(ss); 
    } catch (e) {
      throw new Error("خطأ حرج: لم يتمكن النظام من الوصول لملف البيانات ولا إنشاء ملف جديد. يرجى التأكد من تشغيل التطبيق بصلاحيات (Execute as: Me). التفاصيل: " + e.message);
    }
  }

  return ss;
}

/**
 * Serve the HTML page
 */
