/**
 * Fetch Report Data (Infection Control)
 */
function getReportData(filterType, filterValue) {
  const ss = getSS();
  let sheet = ss.getSheetByName('Data');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('Data'); }

  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return []; // Only headers

  // ... (Rest of existing getReportData logic is preserved) ...
  const headers = data.shift(); // Remove headers
  let filteredData = data;

  const parseDate = (d) => {
    if (d instanceof Date) return d;
    if (typeof d === 'string') return new Date(d);
    return null;
  };

  const formatDateStr = (d) => {
    if (!d) return "";
    const date = parseDate(d);
    if (!date || isNaN(date.getTime())) return "";
    let y = date.getFullYear();
    let m = String(date.getMonth() + 1).padStart(2, '0');
    let day = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  };

  if (filterType === 'daily') {
    filteredData = data.filter(row => {
      const dStr = formatDateStr(row[0]);
      return dStr === filterValue;
    });
  } else if (filterType === 'monthly') {
     const [y, m] = filterValue.split('-');
     filteredData = data.filter(row => row[2] == y && row[1] == parseInt(m));
  } else if (filterType === 'yearly') {
     filteredData = data.filter(row => row[2] == filterValue);
  } else if (filterType === 'range') {
     const start = new Date(filterValue.start);
     start.setHours(0, 0, 0, 0); 
     const end = new Date(filterValue.end);
     end.setHours(23, 59, 59, 999); 

     filteredData = data.filter(row => {
       const d = parseDate(row[0]);
       if (!d) return false;
       return d >= start && d <= end;
     });
  }

  return filteredData.map(row => {
    let r = [...row];
    r[0] = formatDateStr(row[0]); 
    if (r[11] instanceof Date) r[11] = r[11].toISOString();
    return r;
  });
}

