/**
 * Calculate the current Session Number for a specific category in the current month/indicator
 * Max session is 10.
 */
function getKPISessionInfo(inspector, category, indicatorName, dateStr) {
  const ss = getSS();
  let sheet = ss.getSheetByName('KPI_Data');
  if (!sheet) { setupSheet(ss); sheet = ss.getSheetByName('KPI_Data'); }

  const data = sheet.getDataRange().getValues();
  // Headers: 0:Date, 1:Month, 2:Year, 3:Inspector, 4:Category, 5:SessionNum, 6:IndicatorName

  const inputDate = new Date(dateStr);
  const inputMonth = inputDate.getMonth() + 1;
  const inputYear = inputDate.getFullYear();

  // Find max session number for this specific grouping
  let maxSession = 0;

  // We need to look at unique sessions. A session consists of multiple rows (questions).
  // We'll store unique session numbers found.
  const foundSessions = new Set();

  for (let i = 1; i < data.length; i++) {
    const r = data[i];
    if (r[1] == inputMonth && r[2] == inputYear && r[4] == category && r[6] == indicatorName) {
       foundSessions.add(Number(r[5]));
    }
  }

  // Calculate new session
  const count = foundSessions.size;
  const nextSession = count + 1;
  const remaining = 10 - count;

  return {
    nextSession: nextSession,
    remaining: remaining > 0 ? remaining : 0,
    isFull: count >= 10
  };
}

