    if (r[1] == inputMonth && r[2] == inputYear && r[4] == category && r[6] == indicatorName) {
       foundSessions.add(Number(r[5]));
    }
  }

  // Calculate new session
  const count = foundSessions.size;
  const nextSession = count + 1;
  const remaining = 10 - count;

