/**
 * تطبيق مؤشرات الأداء (KPIs) - كود السيرفر
 * يقوم هذا الكود بإنشاء والاتصال بقاعدة بيانات منفصلة تماماً عن التقارير اليومية.
 */

// اسم ملف جوجل شيت الذي سيتم إنشاؤه تلقائياً
const DB_NAME = 'قاعدة بيانات مؤشرات الأداء - KPI Database';

/**
 * دالة الاتصال بقاعدة البيانات
 * تبحث عن ملف الشيت المرتبط، أو تنشئ واحداً جديداً إذا لم تجده.
 */
function getKpiSS() {
  const props = PropertiesService.getScriptProperties();
  const storedId = props.getProperty('KPI_SS_ID');

  let ss;

  // 1. محاولة الفتح باستخدام المعرف المخزن
  if (storedId) {
    try {
      ss = SpreadsheetApp.openById(storedId);
    } catch (e) {
      // المعرف غير صالح أو الملف محذوف
    }
  }

  // 2. إذا لم نجد الملف، ننشئ ملفاً جديداً
  if (!ss) {
    ss = SpreadsheetApp.create(DB_NAME);
    props.setProperty('KPI_SS_ID', ss.getId());
    setupKpiStructure(ss); // تهيئة الأعمدة والصفحات
  }

  return ss;
}

/**
 * تهيئة هيكل قاعدة البيانات (تعمل مرة واحدة عند الإنشاء)
 */
function setupKpiStructure(ss) {
  // 1. صفحة الإعدادات (Settings)
  let settingsSheet = ss.getSheetByName('Settings');
  if (!settingsSheet) {
    settingsSheet = ss.insertSheet('Settings');
    settingsSheet.appendRow(['Key', 'Value']);
    // إعدادات افتراضية
    settingsSheet.appendRow(['admin_password', '11193']);
    settingsSheet.appendRow(['inspectors', JSON.stringify(['د. محمد', 'مس سارة'])]);
    settingsSheet.appendRow(['departments', JSON.stringify(['طوارئ', 'عناية مركزة', 'حضانات', 'عمليات', 'داخلي'])]);
    settingsSheet.appendRow(['categories', JSON.stringify(['أطباء', 'تمريض', 'عمال', 'فنيين'])]);
    settingsSheet.appendRow(['indicators', JSON.stringify([
      {indicator: 'نظافة الأيدي', question: 'هل قام بغسل الأيدي (اللحظة 1)؟', note: 'لم يلتزم قبل لمس المريض', cats: ['أطباء', 'تمريض']},
      {indicator: 'نظافة الأيدي', question: 'هل قام بغسل الأيدي (اللحظة 4)؟', note: 'لم يلتزم بعد لمس المريض', cats: ['أطباء', 'تمريض']},
      {indicator: 'الواقيات الشخصية', question: 'هل يرتدي القفازات عند اللزوم؟', note: 'لم يرتدي القفازات', cats: ['تمريض', 'عمال']}
    ])]);

    // حذف الشيت الافتراضي الفارغ
    const sheet1 = ss.getSheetByName('Sheet1');
    if (sheet1) ss.deleteSheet(sheet1);
  }

  // 2. صفحة البيانات (KPI_Data)
  let dataSheet = ss.getSheetByName('KPI_Data');
  if (!dataSheet) {
    dataSheet = ss.insertSheet('KPI_Data');
    // رؤوس الأعمدة
    dataSheet.appendRow([
      'Date', 'Month', 'Year', 'Inspector', 'Department', 'Category', 
      'Session_Number', 'Indicator', 'Question', 'Answer', 'Note', 'Timestamp'
    ]);
    dataSheet.setFrozenRows(1);
  }
}

/**
