 */
function doGet() {
  return HtmlService.createTemplateFromFile('index')
      .evaluate()
      .setTitle('نظام مؤشرات الأداء (KPIs)')
      .addMetaTag('viewport', 'width=device-width, initial-scale=1')
      .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/**
 * جلب الإعدادات للواجهة
 */
function getAppSettings() {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('Settings');
  const data = sheet.getDataRange().getValues();

  const settings = {};
  for (let i = 1; i < data.length; i++) {
    const key = data[i][0];
    const val = data[i][1];
    try {
      settings[key] = JSON.parse(val);
    } catch (e) {
      settings[key] = val;
    }
  }
  return settings;
}

/**
 * حفظ الإعدادات الجديدة
 */
function saveAppSettings(newSettings) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('Settings');
  sheet.clearContents();
  sheet.appendRow(['Key', 'Value']);

  sheet.appendRow(['admin_password', newSettings.password]);
  sheet.appendRow(['inspectors', JSON.stringify(newSettings.inspectors)]);
  sheet.appendRow(['departments', JSON.stringify(newSettings.departments)]);
  sheet.appendRow(['categories', JSON.stringify(newSettings.categories)]);
  sheet.appendRow(['indicators', JSON.stringify(newSettings.indicators)]);

  return true;
}

/**
 * التحقق من كلمة المرور
 */
function verifyAdminPassword(pass) {
  const settings = getAppSettings();
  return String(settings.admin_password) === String(pass);
}

