 * معرفة رقم الجلسة الحالية
 * (لحساب عدد الجلسات التي تمت لفئة معينة وقسم معين في الشهر الحالي)
 */
function getSessionStatus(inspector, dept, category, indicator, dateStr) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('KPI_Data');
  const data = sheet.getDataRange().getValues();

  const dateObj = new Date(dateStr);
  const m = dateObj.getMonth() + 1;
  const y = dateObj.getFullYear();

  // نجمع أرقام الجلسات الفريدة لهذا المزيج (شهر، سنة، قسم، فئة، مؤشر)
  const uniqueSessions = new Set();

  // تخطي صف العناوين
  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    // row[1]=Month, row[2]=Year, row[4]=Dept, row[5]=Category, row[7]=Indicator, row[6]=SessionNum
    if (row[1] == m && row[2] == y && row[4] == dept && row[5] == category && row[7] == indicator) {
      uniqueSessions.add(Number(row[6]));
    }
  }

  const count = uniqueSessions.size;
  const limit = 10; // الحد الأقصى للجلسات شهرياً

  return {
    nextSession: count + 1,
    currentCount: count,
    remaining: limit - count,
    isFull: count >= limit
  };
}

/**
