function fetchKpiReport(monthStr) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('KPI_Data');
  const data = sheet.getDataRange().getValues();

  if (data.length <= 1) return [];

  const [y, m] = monthStr.split('-');

  // تصفية البيانات حسب الشهر والسنة
  // row[1] = month, row[2] = year
  const filtered = data.slice(1).filter(r => r[2] == y && r[1] == parseInt(m));

  // إرجاع كائنات نظيفة
  return filtered.map(r => ({
