 */
function fetchKpiReport(monthStr) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('KPI_Data');
  const data = sheet.getDataRange().getValues();

  if (data.length <= 1) return [];

  const [y, m] = monthStr.split('-');

  // تصفية البيانات حسب الشهر والسنة
  const filtered = data.slice(1).filter(r => r[2] == y && r[1] == parseInt(m));

  // إرجاع كائنات نظيفة
  return filtered.map(r => ({
    department: r[4],
    category: r[5],
    indicator: r[7],
    question: r[8],
    answer: r[9],
    note: r[10]
  }));
}

/**
 * جلب بيانات لوحة القيادة (Dashboard)
 */
function getDashboardData(indicator, monthStr) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('KPI_Data');
  const data = sheet.getDataRange().getValues();

  if (data.length <= 1) return { monthly: {}, annual: {}, totalInspections: 0, overallCompliance: 0 };

  const [targetYear, targetMonth] = monthStr.split('-').map(Number);

  const monthlyStats = {}; 
  const annualStats = {}; 

  for (let i = 1; i <= 12; i++) {
    annualStats[i] = { total: 0, yes: 0 };
  }

  let globalTotal = 0;
  let globalYes = 0;

  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    // row[1]=Month, row[2]=Year, row[4]=Department, row[5]=Category, row[7]=Indicator, row[9]=Answer

    const rMonth = row[1];
    const rYear = row[2];
    const rCategory = row[5];
    const rIndicator = row[7];
    const rAnswer = row[9];

    // تخطي الإجابات غير المنطبقة (NA)
    if (rAnswer === 'NA') continue;

    if (rIndicator === indicator && rYear === targetYear) {
       // Annual
       if (!annualStats[rMonth]) annualStats[rMonth] = { total: 0, yes: 0 };
       annualStats[rMonth].total++;
       if (rAnswer === 'Yes') annualStats[rMonth].yes++;

       // Monthly
       if (rMonth === targetMonth) {
          if (!monthlyStats[rCategory]) monthlyStats[rCategory] = { total: 0, yes: 0 };
          monthlyStats[rCategory].total++;
          if (rAnswer === 'Yes') monthlyStats[rCategory].yes++;

          globalTotal++;
          if (rAnswer === 'Yes') globalYes++;
       }
    }
  }

  const monthlyLabels = Object.keys(monthlyStats);
  const monthlyData = monthlyLabels.map(cat => {
     const s = monthlyStats[cat];
     return s.total ? Math.round((s.yes / s.total) * 100) : 0;
  });

  const annualLabels = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
  const annualData = [];
  for (let i = 1; i <= 12; i++) {
     const s = annualStats[i];
     annualData.push(s.total ? Math.round((s.yes / s.total) * 100) : 0);
  }

  return {
    monthly: { labels: monthlyLabels, data: monthlyData },
    annual: { labels: annualLabels, data: annualData },
    totalInspections: globalTotal,
    overallCompliance: globalTotal ? Math.round((globalYes / globalTotal) * 100) : 0
  };
}

