/**
 * دالة الاتصال بقاعدة البيانات
 * تبحث عن ملف الشيت المرتبط، أو تنشئ واحداً جديداً إذا لم تجده.
 */
function getKpiSS() {
  const props = PropertiesService.getScriptProperties();
  const storedId = props.getProperty('KPI_SS_ID');

  let ss;

  // 1. محاولة الفتح باستخدام المعرف المخزن
  if (storedId) {
    try {
      ss = SpreadsheetApp.openById(storedId);
    } catch (e) {
      // المعرف غير صالح أو الملف محذوف
    }
  }

  // 2. إذا لم نجد الملف، ننشئ ملفاً جديداً
  if (!ss) {
    ss = SpreadsheetApp.create(DB_NAME);
    props.setProperty('KPI_SS_ID', ss.getId());
    setupKpiStructure(ss); // تهيئة الأعمدة والصفحات
