        indicator: 'الواقيات الشخصية', 
        question: 'هل يرتدي القفازات عند اللزوم؟', 
        note: 'لم يرتدي القفازات', 
        cats: ['تمريض', 'عمال'],
        depts: []
      }
    ])]);

    // حذف الشيت الافتراضي الفارغ
    const sheet1 = ss.getSheetByName('Sheet1');
    if (sheet1) ss.deleteSheet(sheet1);
