/**
 * معرفة رقم الجلسة الحالية
 * (لحساب عدد الجلسات بناءً على المؤشر والتاريخ فقط)
 */
function getSessionStatus(inspector, dept, category, indicator, dateStr) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('KPI_Data');
  const data = sheet.getDataRange().getValues();

  const dateObj = new Date(dateStr);
  const m = dateObj.getMonth() + 1;
  const y = dateObj.getFullYear();

  // نجمع أرقام الجلسات الفريدة
  const uniqueSessions = new Set();

  // تخطي صف العناوين
  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    // row[1]=Month, row[2]=Year, row[7]=Indicator, row[6]=SessionNum
    // تم التعديل: الاعتماد على المؤشر والتاريخ فقط (تجاهل القسم والفئة)
    if (row[1] == m && row[2] == y && row[7] == indicator) {
      uniqueSessions.add(Number(row[6]));
    }
  }

  const count = uniqueSessions.size;
  const limit = 10; // الحد الأقصى للجلسات شهرياً

  return {
    nextSession: count + 1,
    currentCount: count,
    remaining: limit - count,
    isFull: count >= limit
  };
}

/**
 * حفظ استمارة التقييم
 */
function submitKpiForm(form) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('KPI_Data');

  const dateObj = new Date(form.date);
  const month = dateObj.getMonth() + 1;
  const year = dateObj.getFullYear();
  const timestamp = new Date();

  // form.answers عبارة عن مصفوفة من {question, answer}
  const rowsToAppend = form.answers.map(ans => {
    return [
      dateObj,          // 0: Date
      month,            // 1
      year,             // 2
      form.inspector,   // 3
      form.department,  // 4
      form.category,    // 5
      form.sessionNum,  // 6
      form.indicator,   // 7
      ans.question,     // 8
      ans.answer,       // 9
      ans.note || '',   // 10
      timestamp         // 11
    ];
  });

  if (rowsToAppend.length > 0) {
    sheet.getRange(sheet.getLastRow() + 1, 1, rowsToAppend.length, rowsToAppend[0].length)
         .setValues(rowsToAppend);
  }

  return {success: true, session: form.sessionNum};
}

/**
 * جلب بيانات التقرير الشهري
 */
function fetchKpiReport(monthStr) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('KPI_Data');
  const data = sheet.getDataRange().getValues();

  if (data.length <= 1) return [];

  const [y, m] = monthStr.split('-');

  // تصفية البيانات حسب الشهر والسنة
  const filtered = data.slice(1).filter(r => r[2] == y && r[1] == parseInt(m));

  // إرجاع كائنات نظيفة
  return filtered.map(r => ({
    department: r[4],
    category: r[5],
    indicator: r[7],
    question: r[8],
    answer: r[9],
    note: r[10]
  }));
}

/**
 * جلب بيانات لوحة القيادة (Dashboard)
 */
function getDashboardData(indicator, monthStr) {
  const ss = getKpiSS();
  const sheet = ss.getSheetByName('KPI_Data');
  const data = sheet.getDataRange().getValues();

  if (data.length <= 1) return { 
    monthlyCat: { labels:[], data:[] }, 
    monthlyDept: { labels:[], data:[] },
    annual: { labels:[], data:[] }, 
    totalInspections: 0, 
    overallCompliance: 0 
  };

  const [targetYear, targetMonth] = monthStr.split('-').map(Number);

  const catStats = {}; 
  const deptStats = {};
  const annualStats = {}; 

  for (let i = 1; i <= 12; i++) {
    annualStats[i] = { total: 0, yes: 0 };
  }

  let globalTotal = 0;
  let globalYes = 0;

  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    // row[1]=Month, row[2]=Year, row[4]=Department, row[5]=Category, row[7]=Indicator, row[9]=Answer

    const rMonth = row[1];
    const rYear = row[2];
    const rDept = row[4];
    const rCategory = row[5];
    const rIndicator = row[7];
    const rAnswer = row[9];

    // تخطي الإجابات غير المنطبقة (NA)
    if (rAnswer === 'NA') continue;

    if (rIndicator === indicator && rYear === targetYear) {
       // Annual (Yearly Trend for Indicator)
       if (!annualStats[rMonth]) annualStats[rMonth] = { total: 0, yes: 0 };
       annualStats[rMonth].total++;
       if (rAnswer === 'Yes') annualStats[rMonth].yes++;

       // Monthly Breakdown
       if (rMonth === targetMonth) {
          // Category Stats
          if (!catStats[rCategory]) catStats[rCategory] = { total: 0, yes: 0 };
          catStats[rCategory].total++;
          if (rAnswer === 'Yes') catStats[rCategory].yes++;

          // Department Stats
          if (!deptStats[rDept]) deptStats[rDept] = { total: 0, yes: 0 };
          deptStats[rDept].total++;
          if (rAnswer === 'Yes') deptStats[rDept].yes++;

          // Global Stats for Card
          globalTotal++;
          if (rAnswer === 'Yes') globalYes++;
       }
    }
  }

  // Helper to calculate percentages
  const getChartData = (statsObj) => {
    const labels = Object.keys(statsObj);
    const data = labels.map(key => {
      const s = statsObj[key];
      return s.total ? Math.round((s.yes / s.total) * 100) : 0;
    });
    return { labels, data };
  };

  const annualLabels = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
  const annualData = [];
  for (let i = 1; i <= 12; i++) {
     const s = annualStats[i];
     annualData.push(s.total ? Math.round((s.yes / s.total) * 100) : 0);
  }

  return {
    monthlyCat: getChartData(catStats),
    monthlyDept: getChartData(deptStats),
    annual: { labels: annualLabels, data: annualData },
    totalInspections: globalTotal,
    overallCompliance: globalTotal ? Math.round((globalYes / globalTotal) * 100) : 0
  };
}
